BEGIN;

-- Hapus duplikat tarif LAB yang mungkin tercipta akibat script sebelumnya
DELETE FROM kasir_tarif a USING (
    SELECT MIN(id) as min_id, kode
    FROM kasir_tarif
    WHERE jenis = 'LAB'
    GROUP BY kode HAVING COUNT(*) > 1
) b
WHERE a.kode = b.kode AND a.jenis = 'LAB' AND a.id <> b.min_id;

UPDATE ref_lab SET grup_cn = 'A' WHERE kode = 'A0101';
